    표8_상담적용: [
        {"상황":"무력감과 무기력에 시달리는 성도", "성경원리":"인간의 무력함은 부끄러운 것이 아니라 하나님의 능력을 의지하는 시작점입니다", "실제적용":"무기력의 원인을 함께 살펴보되, 인간적 한계를 인정하는 것이 하나님의 능력을 경험하는 길임을 안내하십시오"},
        {"상황":"극도의 두려움과 공황 상태에 있는 성도", "성경원리":"두려움은 자연스러운 감정이지만, 하나님은 두려움보다 크신 분입니다", "실제적용":"두려움을 부정하지 말고 하나님 앞에 정직하게 표현하도록 돕고, '두려워하지 말라'는 하나님의 약속을 반복적으로 묵상하게 하십시오"},
        {"상황":"자신의 능력으로 모든 것을 해결하려는 성도", "성경원리":"인간의 모든 손이 피곤해지고 마음이 녹는 때가 있으며, 이때가 하나님을 의지하는 시작입니다", "실제적용":"자기 능력의 한계를 받아들이는 것이 건강한 신앙의 표현임을 깨닫게 하고, 도움을 구하는 것의 지혜를 나누십시오"}
    ],
    표9_교차참조: [
        {"구절":"여호수아 2:11", "연결점":"우리가 듣자 마음이 녹았고 너희로 말미암아 사람이 정신을 잃었나니", "구분":"구약"},
        {"구절":"에스겔 21:7", "연결점":"모든 손이 약해지며 모든 마음이 녹으며 모든 무릎이 물같이 약해지리라", "구분":"구약"},
        {"구절":"나훔 2:10", "연결점":"텅 비었고 황폐하였도다 마음이 녹으며 무릎이 부딪치며 모든 허리가 아프며 모든 낯이 빛을 잃었도다", "구분":"구약"},
        {"구절":"이사야 2:12-17", "연결점":"만군의 여호와의 날에 교만하고 높은 것이 다 낮아지리라", "구분":"구약"},
        {"구절":"누가복음 21:26", "연결점":"사람들이 세상에 임할 일을 생각하고 무서워 기절하리니", "구분":"신약"},
        {"구절":"요한계시록 6:15-17", "연결점":"땅의 왕들과 큰 자들이 산과 바위에게 이르되 우리를 숨기라 하나님의 진노의 큰 날이 이르렀으니 누가 능히 서리요", "구분":"신약"},
        {"구절":"히브리서 10:31", "연결점":"살아 계신 하나님의 손에 빠져드는 것이 무서울진저", "구분":"신약"},
        {"구절":"히브리서 12:29", "연결점":"우리 하나님은 소멸하는 불이심이라", "구분":"신약"}
    ]
