    표8_상담적용: [
        {"상황":"기도 응답이 늦어져 기다림에 지친 성도", "성경원리":"하나님을 기다린 자는 실망하지 않으며, 그가 정하신 때에 반드시 구원하십니다 (이사야 40:31)", "실제적용":"기다림의 기간이 신앙 성숙의 시간임을 인식하고, 기다리면서도 감사와 찬양의 습관을 유지합니다"},
        {"상황":"신앙에서 기쁨을 잃어버린 성도", "성경원리":"구원의 기쁨은 환경에 좌우되지 않으며, 하나님의 구원 자체가 기쁨의 근원입니다 (하박국 3:18)", "실제적용":"처음 구원받았을 때의 감격을 회상하고, 구원의 의미를 다시 묵상하며 기쁨을 회복합니다"},
        {"상황":"공동체 안에서 외로움을 느끼는 성도", "성경원리":"'우리의 하나님', '우리가 기다렸으니'라는 공동체적 고백은 함께 신앙하는 기쁨을 보여줍니다", "실제적용":"소그룹이나 셀 모임에 참여하여 신앙의 기쁨을 함께 나누고 서로 격려하는 관계를 맺습니다"}
    ],
    표9_교차참조: [
        {"구절":"시편 40:1-3", "연결점":"내가 여호와를 기다리고 기다렸더니 귀를 기울이사 나의 부르짖음을 들으셨도다", "구분":"구약"},
        {"구절":"이사야 40:31", "연결점":"여호와를 앙망하는 자는 새 힘을 얻으리니 독수리같이 날개 치며 올라감이여", "구분":"구약"},
        {"구절":"하박국 3:18", "연결점":"나는 여호와로 말미암아 즐거워하며 나의 구원의 하나님으로 말미암아 기뻐하리로다", "구분":"구약"},
        {"구절":"이사야 12:2", "연결점":"보라 하나님은 나의 구원이시라 내가 신뢰하고 두려움이 없으리니", "구분":"구약"},
        {"구절":"누가복음 2:25-32", "연결점":"시므온이 메시아를 기다리다가 아기 예수를 보고 '내 눈이 주의 구원을 보았사오니' 고백함", "구분":"신약"},
        {"구절":"로마서 8:25", "연결점":"보이지 않는 것을 바라면 인내로 기다릴지니라", "구분":"신약"},
        {"구절":"빌립보서 4:4", "연결점":"주 안에서 항상 기뻐하라 내가 다시 말하노니 기뻐하라", "구분":"신약"},
        {"구절":"히브리서 10:36-37", "연결점":"인내가 너희에게 필요함은 너희가 하나님의 뜻을 행한 후에 약속하신 것을 받기 위함이라", "구분":"신약"}
    ]
