    표8_상담적용: [
        {"상황":"듣기 좋은 메시지만 찾아다니며 영적으로 성장하지 못하는 성도", "성경원리":"부드러운 말만 원하는 것은 영적 미성숙의 표현이며, 바른 가르침을 통해서만 참된 성장이 가능하다", "실제적용":"균형 잡힌 성경 공부 그룹에 참여하도록 안내하고, 불편한 말씀도 사랑의 표현임을 깨닫도록 돕기"},
        {"상황":"목회자에게 '좋은 말만 해달라'고 요구하는 성도", "성경원리":"선지자의 역할은 백성이 원하는 말이 아닌 하나님이 하시는 말씀을 전하는 것이다", "실제적용":"목회자의 역할에 대한 성경적 이해를 함께 공부하고, 진실한 가르침이 궁극적으로 영적 건강을 가져다줌을 인내하며 설명"},
        {"상황":"SNS나 미디어의 왜곡된 기독교 메시지에 영향받은 성도", "성경원리":"거짓것을 예언하라는 요구는 자기 기만의 극치이며, 성경 본문 중심의 바른 교리가 필수적이다", "실제적용":"미디어 리터러시(문해력)를 키우도록 돕고, 모든 가르침을 성경 본문과 대조하는 습관을 세워주기"}
    ],
    표9_교차참조: [
        {"구절":"열왕기상 22:13-14", "연결점":"미가야가 400명의 거짓 선지자 앞에서도 여호와께서 말씀하시는 것만 전하겠다고 선언", "구분":"구약"},
        {"구절":"예레미야 23:16-17", "연결점":"그 선지자들이 여호와의 입에서 나온 것이 아닌 자기 마음의 환상을 말하며 평강이 있으리라 하는도다", "구분":"구약"},
        {"구절":"에스겔 13:10", "연결점":"백성을 유혹하여 평강이 없으나 평강이 있다 하였음이라 - 거짓 평안의 선포", "구분":"구약"},
        {"구절":"미가 2:11", "연결점":"만일 사람이 허풍을 떨며 거짓말로 내가 포도주와 독주에 대하여 네게 예언하리라 할 것 같으면 그 사람이 이 백성의 선지자가 되리로다", "구분":"구약"},
        {"구절":"디모데후서 4:3-4", "연결점":"때가 이르리니 사람이 바른 교훈을 받지 아니하며 귀가 가려워서 자기의 사욕을 따를 스승을 많이 두고", "구분":"신약"},
        {"구절":"갈라디아서 1:6-9", "연결점":"우리나 혹은 하늘로부터 온 천사라도 우리가 너희에게 전한 복음 외에 다른 복음을 전하면 저주를 받을지어다", "구분":"신약"},
        {"구절":"마태복음 24:24", "연결점":"거짓 그리스도들과 거짓 선지자들이 일어나 큰 표적과 기사를 보여 할 수만 있으면 택하신 자들도 미혹하리라", "구분":"신약"},
        {"구절":"데살로니가후서 2:10-12", "연결점":"의의 속임으로 멸망하는 자들에게 임하리니 이는 그들이 진리의 사랑을 받지 아니하여 구원함을 받지 못함이라", "구분":"신약"}
    ]
